(function() {
  const panel = document.querySelector('section[aria-label="fwgr19-n2 Availability panel"]') || 
                document.querySelector('h2')?.closest('section') || 
                document.evaluate('//h2[contains(text(),"fwgr19-n2 Availability")]', document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue?.closest('section');
  if (!panel) return 'not found';
  // Hover over the panel header area to trigger the context menu
  return panel.getBoundingClientRect();
})()

(function(){
  const regions = Array.from(document.querySelectorAll('[role="region"], section'));
  const panel = regions.find(r => r.getAttribute('aria-label') === 'fwgr19-n2 Availability' || r.querySelector('h2')?.textContent === 'fwgr19-n2 Availability');
  if (!panel) return 'panel not found';
  const menuBtn = panel.querySelector('button[aria-label*="Menu"], button[aria-label*="menu"]');
  return menuBtn ? {aria: menuBtn.getAttribute('aria-label'), id: menuBtn.id} : 'no menu button';
})()

(function(){
  const menuBtn = document.querySelector('button[aria-label="Menu for panel with title fwgr19-n2 Availability"]');
  if (!menuBtn) return 'not found';
  menuBtn.click();
  return 'clicked';
})()
